 vaInputs.user_badges_count = '';
 var baseURL = gs.getProperty('glide.servlet.uri');
 var images = {};
 images['PERMANENT_BADGE'] = baseURL + '/x_aleen_aia_skills.permanentbadge.png';
 images['TEMP_BADGE'] = baseURL + '/x_aleen_aia_skills.visitorbadge.png';
 images['MOBILE_CREDENTIAL'] = baseURL + '/x_aleen_aia_skills.digitalbadge.png';

 var identityId = vaInputs.user_sys_id;
 var badgeAction = vaInputs.badge_action;
 var badgeArray = [];

 var badgeGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset');
 badgeGr.addQuery('identity', identityId);
 badgeGr.addNotNullQuery('status');
 badgeGr.addQuery('is_deleted', false);
 if (badgeAction == "activate") {
 badgeGr.addQuery('status.code', 'INACTIVE');
 } else {
 badgeGr.addQuery('status.code', 'ACTIVE');
 }
 badgeGr.query();
 while (badgeGr.next()) {
 badgeArray.push({
 'name': badgeGr.getDisplayValue("asset.serial"),
 'value': badgeGr.getValue("sys_id"),
 'description': badgeGr.getDisplayValue("asset.type"),
 'body': images[badgeGr.getDisplayValue("asset.type.code")]
 });
 }
 vaVars.user_badges = badgeArray;
 if(badgeArray.length > 0) {
 vaInputs.user_badges_count = badgeArray.length;
 }


})()
